// Generated by `cargo xtask grammar-fix`.
// Round-trip regression test for the generated test suite.
//
// Card           : Earthbind
// Set            : lea
// Collector #    : 145

#[test]
fn round_trip() {
    let text = "Enchant creature\nWhen this Aura enters, if enchanted creature has flying, this Aura deals 2 damage to that creature and this Aura gains \"Enchanted creature loses flying.\"";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}

